   AND old.expiration_date IS NULL;

ON CONFLICT (id) DO UPDATE SET
  value           = EXCLUDED.value,
  coverage_status = EXCLUDED.coverage_status,
  source_quote    = EXCLUDED.source_quote,
  effective_date  = EXCLUDED.effective_date,
  confidence      = EXCLUDED.confidence,
  expiration_date = EXCLUDED.expiration_date;

COMMIT;

SELECT p.name AS payer, pr.state, pr.coverage_status, count(*) AS codes
  FROM payer_rule pr JOIN payer p ON p.id = pr.payer_id
 WHERE pr.created_by = 'extract:fee-schedules-full-2026-08'
 GROUP BY 1,2,3 ORDER BY 1,2,3;
